for section in ['persistent-apps','recent-apps','persistent-others']:
 for i,item in enumerate(p.get(section,[])):
  d=item.get('tile-data',{});label=d.get('file-label','');url=d.get('file-data',{}).get('_CFURLString','')
  if 'mesh' in (label+' '+url+str(d.get('bundle-identifier',''))).lower(): print(json.dumps({'section':section,'index':i,'label':label,'url':url,'bundle':d.get('bundle-identifier'),'keys':list(d)}))
print('sections', {k:len(p.get(k,[])) for k in ['persistent-apps','recent-apps','persistent-others']})
PY
