from pathlib import Path
import os,plistlib,json
for folder in [Path('/Applications'),Path('/Users/kingsonwu/Applications')]:
 if not folder.exists():continue
 for p in folder.iterdir():
  if 'mesh' not in p.name.lower():continue
  try:
   st=p.stat();info=plistlib.loads((p/'Contents/Info.plist').read_bytes()) if p.is_dir() else {}
   print(json.dumps({'path':str(p),'resolved':str(p.resolve()),'inode':st.st_ino,'symlink':p.is_symlink(),'bundle':info.get('CFBundleIdentifier'),'version':info.get('CFBundleShortVersionString')}))
  except Exception as e:print(str(p),type(e).__name__)
PY
