pub struct DiscoveryVisibility {
    public: RwLock<bool>,
    physical_lan_only: AtomicBool,
    inventory: Arc<dyn Fn() -> Vec<LanInterface> + Send + Sync>,
    changes: tokio::sync::watch::Sender<u64>,
