import http.server,urllib.parse,pathlib,hashlib,subprocess,threading,signal,os,json,shutil
root=pathlib.Path(__file__).resolve().parent
cache=root/'diagnostics-apt-cache';cache.mkdir(exist_ok=True)
active=set();guard=threading.Lock()
class Handler(http.server.BaseHTTPRequestHandler):
 def do_GET(self):
  u=urllib.parse.urlsplit(self.path)
  if u.scheme not in ('http','https') or u.hostname not in ('archive.ubuntu.com','security.ubuntu.com') or u.username or u.password or u.port not in (None,80,443):
   self.send_error(403);return
  url=urllib.parse.urlunsplit(('https',u.netloc,u.path,u.query,''))
  path=cache/hashlib.sha256(url.encode()).hexdigest()
  if not path.exists():
   temp=path.with_name(path.name+'.'+str(threading.get_ident()))
   try:
    p=subprocess.Popen(['/usr/bin/curl','--fail','--silent','--show-error','--location','--proto','=https','--proto-redir','=https','--connect-timeout','10','--max-time','90','--output',str(temp),url],stdout=subprocess.DEVNULL,stderr=subprocess.PIPE,start_new_session=True)
    with guard:active.add(p)
    _,error=p.communicate()
    with guard:active.discard(p)
    if p.returncode:raise RuntimeError('verified upstream download failed')
    temp.replace(path)
   except Exception:
    temp.unlink(missing_ok=True);self.send_error(502);return
  self.send_response(200);self.send_header('Content-Length',str(path.stat().st_size));self.send_header('Connection','close');self.end_headers()
  try:
   with path.open('rb') as body:shutil.copyfileobj(body,self.wfile,65536)
  except (BrokenPipeError,ConnectionResetError):pass
 def log_message(self,*args):pass
server=http.server.ThreadingHTTPServer(('127.0.0.1',0),Handler)
(root/'diagnostics-apt-proxy.json').write_text(json.dumps({'pid':os.getpid(),'port':server.server_port}))
def stop(*args):
 with guard:children=list(active)
 for p in children:
  try:os.killpg(p.pid,signal.SIGTERM)
  except ProcessLookupError:pass
 for p in children:
  try:p.wait(timeout=5)
  except subprocess.TimeoutExpired:os.killpg(p.pid,signal.SIGKILL);p.wait()
 raise KeyboardInterrupt
signal.signal(signal.SIGTERM,stop)
try:server.serve_forever()
except KeyboardInterrupt:pass
finally:server.server_close()
